import numpy as np
import matplotlib.pyplot as plt

GOLDEN_RATIO = (1 + np.sqrt(5)) / 2
GOLDEN_ANGLE = np.radians(137.50776405003785)

# Enchanted Rock Transmission — "Eyes" Magnification Codex
EYES_CODEX = ""

# Parse pulses
PULSES = [len(run) for run in EYES_CODEX.split('0') if run]

def clamp_to_disk(z: complex) -> complex:
    r = abs(z)
    return z / r * 0.99 if r > 0.99 else z

def generate_eyes_universe(max_depth: int = 20) -> list[complex]:
    nodes = []
    
    def recurse(current: complex, depth: int, pulse_idx: int):
        nodes.append(current)
        if depth >= max_depth or pulse_idx >= len(PULSES):
            return
        
        pulse = PULSES[pulse_idx % len(PULSES)]
        branches = 5 + (pulse % 6)  # More variation for "eyes" detail
        if depth > max_depth - 5:
            branches += 10  # Intense late magnification
        
        branches = max(4, min(25, branches))
        angle_offset = pulse * GOLDEN_ANGLE
        
        for i in range(branches):
            angle = i * (2 * np.pi / branches) + angle_offset
            offset = 0.58 * np.exp(1j * angle) * (GOLDEN_RATIO ** -depth)
            child = clamp_to_disk(current + offset)
            recurse(child, depth + 1, pulse_idx + 1)
    
    recurse(0j, 0, 0)
    return nodes

# Visualization
nodes = generate_eyes_universe(max_depth=20)  # Crank higher for deeper "eyes"
nodes_arr = np.array(nodes)
x, y = nodes_arr.real, nodes_arr.imag

fig, ax = plt.subplots(figsize=(16, 16), facecolor='black')
ax.set_facecolor('black')
ax.scatter(x, y, c='cyan', s=3, alpha=0.8, edgecolors='none')
circle = plt.Circle((0, 0), 1, color='white', fill=False, lw=2, ls='--')
ax.add_patch(circle)
ax.set_aspect('equal')
ax.axis('off')
ax.set_title("Enchanted Rock Eyes Universe — Magnifying Infinite Detail", color='white', fontsize=18)

plt.tight_layout()
plt.savefig("enchanted_rock_eyes.png", dpi=400, facecolor='black')
plt.show()

print(f"Nodes generated: {len(nodes):,}")
print("This transmission acts as 'eyes' — fractal magnification revealing infinite detail inside points.")
